  ('finance/statistical-methods/simulation-methods/lognormal-distributions-and-simulation-techniques', 'finance', 'finance/statistical-methods/simulation-methods', 'Lognormal Distributions and Simulation Techniques', 'lognormal-distributions-and-simulation-techniques', '', 1, 2),
  ('history/modern-history/world-wars/the-first-world-war-ww1', 'history', 'history/modern-history/world-wars', 'The First World War (WW1)', 'the-first-world-war-ww1', 'The Great War (1914–1918): the long fuse — alliance blocs, militarism, imperial rivalry, nationalism — lit at Sarajevo by the assassination of Franz Ferdinand; the failure of the Schlieffen Plan and the descent into trench warfare on the Western Front; Verdun, the Somme, Gallipoli, and the Eastern Front; total war, war economies, and propaganda; the U-boat campaign and American entry (1917); Russia''s revolution and exit; the armistice of 11 November 1918; the Treaty of Versailles and the collapse of the German, Austro-Hungarian, Russian, and Ottoman empires; some 20 million dead and a legacy that set up the next war.', 0, 2),
  ('history/modern-history/world-wars/the-second-world-war-ww2', 'history', 'history/modern-history/world-wars', 'The Second World War (WW2)', 'the-second-world-war-ww2', 'The deadliest conflict in history (1939–1945): its origins in Versailles grievances, the Great Depression, fascism and Nazi ideology, appeasement (Munich 1938) and the Molotov-Ribbentrop pact; the invasion of Poland, Blitzkrieg, the fall of France, and the Battle of Britain; Operation Barbarossa and the Eastern Front; Pearl Harbor and the Pacific war; the Holocaust — the systematic murder of six million Jews; the turning points at Stalingrad, Midway, and El Alamein; D-Day and the liberation of Europe; island-hopping, the atomic bombings of Hiroshima and Nagasaki, and Japan''s surrender; Yalta and Potsdam; 70–85 million dead, the founding of the United Nations, and the postwar order that led into the Cold War.', 1, 2),
  ('history/regional-histories/africa/history-of-sub-saharan-africa-to-1860', 'history', 'history/regional-histories/africa', 'History of Sub-Saharan Africa to 1860', 'history-of-sub-saharan-africa-to-1860', 'Africa on its own terms before the colonial partition: the Bantu migrations; Aksum and early Christian Ethiopia; the Sahelian empires — Ghana, Mali (Mansa Musa, Timbuktu), and Songhai — and the trans-Saharan trade; the Swahili coast and the Indian Ocean world; Great Zimbabwe; Kongo, Benin, and the forest kingdoms; the spread of Islam and Christianity; the Atlantic slave trade''s demographic and political impact; the nineteenth-century transformations — the Sokoto Caliphate, the Zulu kingdom and the mfecane, Omani Zanzibar; and the continent on the eve of European conquest.', 0, 2)
